 var help=sell.GetComponentInChildren<Canvas>(true);if(help!=null){help.transform.localPosition=new Vector3(0,1.05f,.75f);help.transform.localScale=Vector3.one*.004f;PrefabUtility.RecordPrefabInstancePropertyModifications(help.transform);}
